                reason: 'stale agent:rework after review (dead letter re-fire)' });
        } else {
            actions.push({ type: 'skip',
                reason: 'reviewed, verdict not approve — awaiting rework labeling' });
        }
        return actions;
    }

    actions.push({ type: 'skip', reason: 'steady state' });
