                a.type + (a.leg ? ':' + a.leg : '') + ' — ' + a.reason);
            if (cfg.dryRun) { acted++; if (a.type === 'dispatch') dispatched++; return; }
            try {
                executeAction(provider, a, issue, cfg);
                acted++;
                if (a.type === 'dispatch') dispatched++;
