            './configLoader.js': configLoaderModule,
            './common/outputFiles.js': outputFiles,
            './developTicketAndCreatePR.js': { action: function() { return { success: true, path: 'delegated' }; } }
        ,
            './common/commentMarkup.js': commentMarkupModule,
        }),
        allMocks
