                    reviewStarted = autoStart.triggerConfiguredWorkflowForTicket({
                        ticketKey: ticketKey,
                        customParams: customParams,
                        config: config,
                        configFile: reviewConfigFile,
                        label: 'pr_review',
                        scm: _scm,
                        stripKeys: [
                            'removeLabel',
                            'autoStartReview',
                            'autoStartReviewConfigFile'
                        ]
                    });
                } catch (e) {
