    );
var commentMarkupModule = loadModule('js/common/commentMarkup.js');
var gitStagingModule = loadModule('js/common/gitStaging.js');

    var mod = loadModule(
        'js/developBugAndCreatePR.js',
        makeRequire({
            './config.js': configModule,
