    }

    const m = commentMarkup.forTicket(ticketKey);
    let comment = m.h(3, '🚫 Bug Cannot Be Fixed Automatically') + '\n\n';
    comment += m.bold('Reason') + ': ' + (blocked.reason || '(see details below)') + '\n\n';
